if nvda.empty:
    raise ValueError(
        f"No completed NVDA market data available for {BACKFILL_DATE}"
    )

actual_volume = int(
    nvda["Volume"].iloc[0].item()
)

print("Backfill date:", BACKFILL_DATE)
print("Actual NVDA volume:", f"{actual_volume:,}")

def prepare_ml_columns(df):

    result = df

    for c in NUMERIC_FEATURES:
        result = result.withColumn(
            c,
            F.coalesce(
                F.col(c).cast("double"),
                F.lit(0.0)
            )
        )

    for c in BOOLEAN_FEATURES:
        result = result.withColumn(
            c,
            F.coalesce(
                F.col(c).cast("boolean"),
                F.lit(False)
            )
        )

    result = result.withColumn(
        LABEL_COL,
        F.col(LABEL_COL).cast("double")
    )

    return result

if retrain_required:

    print("Saving candidate model to staging...")

    (
        new_model.write()
        .overwrite()
        .save(MODEL_STAGING_PATH)
    )

    # Smoke test the saved model
    candidate_model = PipelineModel.load(
        MODEL_STAGING_PATH
    )

    smoke_df = candidate_model.transform(
        training_df.limit(5)
    )

    smoke_count = (
        smoke_df
        .filter(F.col("prediction").isNotNull())
        .count()
    )

    if smoke_count == 0:
        raise RuntimeError(
            "Candidate model smoke test failed."
        )

    print(
        "Candidate model validated successfully."
    )

else:
    print("No candidate model created.")
